import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ProactiveDemo {

    private static final Logger log = Logger.getLogger(ProactiveDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Projecting connection-pool trend at " + BANK_NAME);

        int poolLimit = 100;
        List<UsageReading> readings = new ArrayList<>();
        // Slowly creeping upward — a subtle leak, no alarm yet.
        readings.add(new UsageReading(1, 40));
        readings.add(new UsageReading(2, 48));
        readings.add(new UsageReading(3, 56));
        readings.add(new UsageReading(4, 64));
        readings.add(new UsageReading(5, 72));

        TrendProjector projector = new TrendProjector(poolLimit, 7);
        double growthPerDay = projector.dailyGrowth(readings);
        int daysToLimit = projector.daysToLimit(readings);

        log.info(() -> "Current usage " + readings.get(readings.size() - 1).getValue()
                + "/" + poolLimit + ", growing ~" + growthPerDay + " per day.");

        if (projector.isConcerning(readings)) {
            log.warning(() -> "EARLY WARNING: pool exhausts in ~" + daysToLimit
                    + " days at this rate. Investigate the connection leak NOW, before any outage.");
        } else {
            log.info(() -> "Trend is safe: ~" + daysToLimit + " days of headroom.");
        }
    }
}

